/**
 * Lazy loader for the Canada provinces/territories map
 * (src/data/canada/provinces-50m.json, ~60 KB, ~23 KB gzipped).
 *
 * Loaded through a dynamic import so Vite gives it its own chunk and the US
 * screens never download it. Nothing imports this module yet (data only).
 *
 * Each feature's `id` is the postal abbreviation from src/data/canada.ts.
 * Generated by scripts/build-canada-topo.mjs from Natural Earth (public domain).
 */
import type { GeometryCollection, Topology } from 'topojson-specification';

export type CanadaTopology = Topology<{ provinces: GeometryCollection }>;

let cached: Promise<CanadaTopology> | null = null;

export function loadCanadaTopology(): Promise<CanadaTopology> {
  cached ??= import('./canada/provinces-50m.json').then((m) => m.default as unknown as CanadaTopology);
  return cached;
}
